async function syncStateToDatabase(env, data, shouldNotify) {
  const initialized = (await getSetting(env, "auto_initialized")) === "1";
  const events = [];
  const rounds = Array.isArray(data.rounds) ? data.rounds : [];

  for (const round of rounds) {
    if (!publishedRound(round)) continue;
    const record = resultRecordFromRound(data, round);
    if (!record.roundTime || !record.result) continue;
    const result = await upsertResult(env, record);
    if (["new", "changed", "pending"].includes(result.state)) events.push(result);
  }

  if (!initialized) {
    for (const event of events) await markResultNotified(env, event.record);
    await setSetting(env, "auto_initialized", "1");
  } else if (shouldNotify) {
    for (const event of events) {
      const text = resultNotificationText(event.record, event.state === "changed");
      try {
        await notifyAllDestinationsWithPhoto(env, text, notificationKeyboard());
      } catch (error) {
        console.error("Screenshot/photo notification failed; using text fallback", error);
        await notifyAllDestinations(env, text, { reply_markup: notificationKeyboard() });
      }
      await markResultNotified(env, event.record);
    }
  }

  const status = normalizeStatus(data);
  const previousStatus = await getSetting(env, "last_app_status");
  if (!previousStatus) {
    await setSetting(env, "last_app_status", status.key);
  } else if (previousStatus !== status.key && status.kind !== "UNKNOWN") {
    if (!initialized) {
      await setSetting(env, "last_app_status", status.key);
    } else if (shouldNotify) {
      await notifyAllDestinations(env, formatStatusMessage(data), {
        reply_markup: statusKeyboard(),
      });
      await setSetting(env, "last_app_status", status.key);
    }
  }

  return { initialized, eventCount: events.length, status: status.key };
}

function formatLiveMessage(data) {
  const live = data.live || {};
  const rounds = Array.isArray(data.rounds) ? data.rounds : [];
  const status = normalizeStatus(data);
  const liveResult = validResult(live.result) || "--";
  const lines = [
    "🇲🇲 TarTay 2D Live",
    "",
    `📅 Date — ${displayDate(normalizeApiDate(data.date))}`,
    `${statusEmoji(status.kind)} Status — ${status.raw}`,
    `📊 SET — ${live.set || "--"}`,
    `💰 VALUE — ${live.value || "--"}`,
    `🎯 LIVE 2D — ${liveResult}`,
    "",
    "📋 ယနေ့ထွက်ဂဏန်းများ",
  ];

  if (rounds.length === 0) {
    lines.push("ဂဏန်းစာရင်း မရရှိသေးပါ");
  } else {
    for (const round of rounds) {
      const result = publishedRound(round) ? validResult(round.result) : null;
      lines.push(`${timeIcon(round.time)} ${normalizeRoundTime(round.time) || "--"} — ${result || "စောင့်ဆိုင်းနေဆဲ"}`);
    }
  }

  lines.push("", `🔄 Updated — ${live.updatedAt || "Just now"}`);
  return lines.join("\n");
}

