async function resultsForDate(env, dateString) {
  const response = await env.DB.prepare(`
    SELECT result_date, round_time, result, set_value, market_value
    FROM results
    WHERE result_date = ?
    ORDER BY CASE round_time
      WHEN '09:00 AM' THEN 1
      WHEN '11:00 AM' THEN 2
      WHEN '01:00 PM' THEN 3
      WHEN '03:00 PM' THEN 4
      WHEN '05:00 PM' THEN 5
      WHEN '07:00 PM' THEN 6
      ELSE 99 END
  `).bind(dateString).all();
  return response.results || [];
}

function formatDayHistory(dateString, rows, showWaiting = false) {
  const byTime = new Map(rows.map((row) => [normalizeRoundTime(row.round_time), row]));
  const lines = ["📜 TarTay 2D မှတ်တမ်း", "", `📅 ${displayDate(dateString)}`, ""];

  for (const item of ROUND_SCHEDULE) {
    const row = byTime.get(item.time);
    const value = row?.result || (showWaiting ? "စောင့်ဆိုင်းနေဆဲ" : "မှတ်တမ်းမရှိ");
    lines.push(`${item.icon} ${item.time} — ${value}`);
  }
  return lines.join("\n");
}

