async function sendSevenDayHistory(env, chatId) {
  try {
    const data = await fetchLiveState();
    await syncStateToDatabase(env, data, false);
  } catch (error) {
    console.error("7-day history sync failed", error);
  }

  const end = todayMyanmar();
  const start = shiftCanonicalDate(end, -6);
  const response = await env.DB.prepare(`
    SELECT result_date, round_time, result
    FROM results
    WHERE result_date BETWEEN ? AND ?
    ORDER BY result_date DESC,
      CASE round_time
        WHEN '09:00 AM' THEN 1
        WHEN '11:00 AM' THEN 2
        WHEN '01:00 PM' THEN 3
        WHEN '03:00 PM' THEN 4
        WHEN '05:00 PM' THEN 5
        WHEN '07:00 PM' THEN 6
        ELSE 99 END
  `).bind(start, end).all();

  const groups = new Map();
  for (const row of response.results || []) {
    if (!groups.has(row.result_date)) groups.set(row.result_date, []);
    groups.get(row.result_date).push(row);
  }

  const lines = ["🗓 TarTay 2D — ၇ ရက်စာမှတ်တမ်း", ""];
  for (let offset = 0; offset < 7; offset += 1) {
    const date = shiftCanonicalDate(end, -offset);
    const rows = groups.get(date) || [];
    if (rows.length === 0) continue;
    lines.push(`📅 ${displayDate(date)}`);
    for (const row of rows) lines.push(`${timeIcon(row.round_time)} ${row.round_time} — ${row.result}`);
    lines.push("");
  }
  if (groups.size === 0) lines.push("ပြီးခဲ့တဲ့ ၇ ရက်အတွင်း သိမ်းထားသောမှတ်တမ်း မရှိသေးပါ။");

  await telegramRequest(env.BOT_TOKEN, "sendMessage", {
    chat_id: chatId,
    text: lines.join("\n").slice(0, 4096),
    reply_markup: historyKeyboard(),
  });
}

